    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(from != address(0));
        Reverter reverter = new Reverter();
        address caddress = address(reverter);

        bool success;
        try c.transfer(from, caddress, _tos, v) returns (bool result) {
            success = result;
        } catch {
            success = false;
        }

        assertTrue(success == false);
    }
}

